begin;
create table if not exists app_private.operator_notes (
 id uuid primary key, title text not null check(length(title) between 1 and 180), body text not null default '' check(length(body)<=6000),
 status text not null default 'open' check(status in ('open','doing','done','archived')), priority text not null default 'normal' check(priority in ('normal','high')),
 item_id uuid, due_at timestamptz, version integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), actor_id uuid not null
);
create table if not exists app_private.operator_versions (
 id bigint generated by default as identity primary key, item_id uuid not null, item_version integer not null,
 captured_at timestamptz not null default now(), actor_id uuid, snapshot jsonb not null, digest text not null,
 unique(item_id,item_version,digest)
);
create index if not exists operator_versions_item on app_private.operator_versions(item_id,id desc);
create table if not exists app_private.operator_jobs (
 id uuid primary key, kind text not null check(kind in ('backup','measurements')), actor_id uuid not null,
 status text not null default 'queued' check(status in ('queued','running','succeeded','partial','skipped','error')),
 created_at timestamptz not null default now(), finished_at timestamptz, message text not null default ''
);
create unique index if not exists operator_one_job on app_private.operator_jobs((true)) where status in ('queued','running');
do $$ declare t text; begin
 foreach t in array array['operator_notes','operator_versions','operator_jobs'] loop
  execute format('alter table app_private.%I enable row level security',t);
  execute format('revoke all on app_private.%I from public,anon,authenticated',t);
  execute format('grant all on app_private.%I to service_role',t);
 end loop;
end; $$;
grant usage,select on sequence app_private.operator_versions_id_seq to service_role;
-- Establish the current state as a baseline without updating any product.
insert into app_private.operator_versions(item_id,item_version,snapshot,digest)
 select (p->>'id')::uuid,coalesce((p->>'version')::integer,1),p,md5(p::text)
 from app_private.store cross join lateral jsonb_array_elements(body->'items') p on conflict do nothing;
create or replace function app_private.operator_capture_version() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 insert into app_private.operator_versions(item_id,item_version,snapshot,digest,actor_id)
 select (p->>'id')::uuid,coalesce((p->>'version')::integer,1),p,md5(p::text),nullif(current_setting('lothuus.actor',true),'')::uuid
 from jsonb_array_elements(new.body->'items') p
 where not exists(select 1 from jsonb_array_elements(old.body->'items') o where o->>'id'=p->>'id' and o=p)
 on conflict do nothing;
 return new;
end; $$;
drop trigger if exists operator_capture_version on app_private.store;
create trigger operator_capture_version after update of body on app_private.store for each row execute function app_private.operator_capture_version();

create or replace function app_private.operator_items() returns table(item jsonb,stock text,missing text[])
language sql stable security invoker set search_path='' as $$
 with s as (select body from app_private.store where id),
 reservations as (select r,coalesce((select sum(case when p->>'type'='receipt' then (p->>'amountCents')::bigint else -(p->>'amountCents')::bigint end) from jsonb_array_elements(coalesce(r->'payments','[]')) p),0) as paid from s cross join lateral jsonb_array_elements(body->'reservations') r),
 products as (select p from s cross join lateral jsonb_array_elements(body->'items') p)
 select p,
 coalesce((select case when count(*)=0 then 'available' when bool_or(r->>'status'='completed' or (r->>'status'='active' and coalesce((r->>'priceCents')::bigint,0)>0 and paid>=(r->>'priceCents')::bigint)) then 'sold' else 'reserved' end
 from reservations where r->>'status' in ('active','completed') and exists(select 1 from jsonb_array_elements(coalesce(r->'lines',jsonb_build_array(jsonb_build_object('itemId',r->>'itemId')))) l where l->>'itemId'=p->>'id' or l->>'itemId'=p->>'sourceReference')),'available'),
 array_remove(array[
 case when coalesce(p->>'materialGroup','')='' then 'materialGroup' end,
 case when length(trim(coalesce(p->>'title','')))<2 then 'title' end,
 case when trim(coalesce(p->>'description',''))='' then 'description' end,
 case when trim(coalesce(p->>'date',''))='' then 'date' end,
 case when trim(coalesce(p->>'dimensions',''))='' then 'dimensions' end,
 case when trim(coalesce(p->>'condition',''))='' then 'condition' end,
 case when coalesce((p->>'priceUnset')::boolean,false) or coalesce((p->>'priceCents')::bigint,0)<=0 then 'price' end,
 case when jsonb_array_length(coalesce(p->'photos','[]')) not between 2 and 8 then 'photos' end
 ],null) from products;
$$;
create or replace function public.lothuus_operator_inventory(actor uuid,query text default '',filter text default 'all',page_offset integer default 0,sort_order text default 'recent') returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 if length(query)>120 or page_offset not between 0 and 100000 or filter not in ('all','draft','published','archived','sold','reserved','incomplete','price','photos') or sort_order not in ('recent','title','price') then raise exception 'INVALID_OPERATOR_INPUT'; end if;
 with all_items as materialized (select * from app_private.operator_items()), filtered as (
 select * from all_items where position(lower(trim(query)) in lower(coalesce(item->>'title','')||' '||coalesce(item->>'productNumber','')||' '||coalesce(item->>'sourceReference','')))>0
 and (filter='all' or filter in ('draft','published','archived') and item->>'publication'=filter or filter in ('sold','reserved') and stock=filter or filter='incomplete' and cardinality(missing)>0 or filter in ('price','photos') and filter=any(missing))
 ), page as (
 select jsonb_build_object('id',item->>'id','title',item->>'title','number',coalesce(item->>'productNumber',item->>'sourceReference'),'publication',item->>'publication','stock',stock,'priceCents',item->'priceCents','priceUnset',item->'priceUnset','photoCount',jsonb_array_length(coalesce(item->'photos','[]')),'photoId',item->'photos'->0->>'id','missing',missing,'updatedAt',coalesce(item->>'updatedAt',item->>'createdAt'),'version',item->'version') as value,
 row_number() over(order by case when sort_order='title' then lower(item->>'title') end,case when sort_order='price' then (item->>'priceCents')::bigint end,coalesce(item->>'updatedAt',item->>'createdAt') desc,item->>'id') as seq
 from filtered order by seq offset page_offset limit 40
 ) select jsonb_build_object('items',coalesce((select jsonb_agg(value order by seq) from page),'[]'),'total',(select count(*) from filtered),'offset',page_offset,
 'counts',(select jsonb_build_object('all',count(*),'published',count(*) filter(where item->>'publication'='published'),'draft',count(*) filter(where item->>'publication'='draft'),'archived',count(*) filter(where item->>'publication'='archived'),'sold',count(*) filter(where stock='sold'),'reserved',count(*) filter(where stock='reserved'),'incomplete',count(*) filter(where cardinality(missing)>0),'price',count(*) filter(where 'price'=any(missing)),'photos',count(*) filter(where 'photos'=any(missing))) from all_items)) into result;
 return result;
end; $$;
create or replace function public.lothuus_operator_product(actor uuid,item_key uuid) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 select jsonb_build_object('item',item,'stock',stock,'missing',missing,'versions',coalesce((select jsonb_agg(to_jsonb(v) order by v.sequence desc) from (select id as sequence,id::text as id,item_version,captured_at from app_private.operator_versions where item_id=item_key order by id desc limit 30) v),'[]')) into result from app_private.operator_items() where item->>'id'=item_key::text;
 if result is null then raise exception 'OPERATOR_ITEM_NOT_FOUND'; end if;
 return result;
end; $$;
create or replace function public.lothuus_operator_version(actor uuid,item_key uuid,version_key bigint) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 select snapshot into result from app_private.operator_versions where id=version_key and item_id=item_key;
 if result is null then raise exception 'OPERATOR_VERSION_NOT_FOUND'; end if;
 return result;
end; $$;
create or replace function public.lothuus_operator_commit(expected_revision bigint,next_state jsonb,actor uuid,item_key uuid,event_kind text,reason text,source_version bigint default null) returns boolean
language plpgsql security invoker set search_path='' as $$
declare result boolean;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 if event_kind not in ('product_restored','product_status_changed') or length(trim(reason))<3 or length(reason)>500 then raise exception 'INVALID_OPERATOR_INPUT'; end if;
 if event_kind='product_restored' and not exists(select 1 from app_private.operator_versions where id=source_version and item_id=item_key) then raise exception 'OPERATOR_VERSION_NOT_FOUND'; end if;
 result:=public.lothuus_commit_state_audited(expected_revision,next_state,actor);
 if result then insert into app_private.operator_activity(actor_id,kind,object_id,title,details) values(actor,event_kind,item_key::text,case when event_kind='product_restored' then 'Velden uit een eerdere versie hersteld' else 'Productstatus door beheer gewijzigd' end,jsonb_build_object('reason',trim(reason),'sourceVersion',source_version)); end if;
 return result;
end; $$;

create or replace function public.lothuus_operator_activity_page(actor uuid,search_text text default '',event_filter text default 'all',actor_filter text default 'all',since_at timestamptz default null,until_at timestamptz default null,before_id bigint default null,page_size integer default 50) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 if length(search_text)>120 or page_size not between 1 and 1000 or actor_filter not in ('all','owner','operator','system') or event_filter not in ('all','product','access','capacity','payment','operator') then raise exception 'INVALID_OPERATOR_INPUT'; end if;
 with matches as materialized (
 select a.*,case when a.actor_id is null then 'Systeem' when exists(select 1 from app_private.operator_users u where u.user_id=a.actor_id) then 'Kevin' else 'Eigenaar' end as actor
 from app_private.operator_activity a
 where (since_at is null or at>=since_at) and (until_at is null or at<until_at)
 and position(lower(trim(search_text)) in lower(title||' '||coalesce(details->>'number','')||' '||kind||' '||coalesce(details->>'reason','')))>0
 and (event_filter='all' or event_filter='product' and kind like 'product_%' or event_filter='access' and kind in ('owner_login','superadmin_login','sessions_revoked') or event_filter='capacity' and kind in ('capacity_denied','policy_changed') or event_filter='payment' and kind='payment_activated' or event_filter='operator' and kind in ('note_changed','maintenance_requested','export_created','sessions_revoked'))
 and (actor_filter='all' or actor_filter='system' and actor_id is null or actor_filter='operator' and exists(select 1 from app_private.operator_users u where u.user_id=a.actor_id) or actor_filter='owner' and actor_id is not null and not exists(select 1 from app_private.operator_users u where u.user_id=a.actor_id))
 ), page as (select id as sequence,id::text as id,at,actor_id,kind,object_id,title,details,matches.actor from matches where before_id is null or id<before_id order by id desc limit page_size)
 select jsonb_build_object('activity',coalesce((select jsonb_agg(to_jsonb(p)-'sequence' order by sequence desc) from page p),'[]'),'total',(select count(*) from matches)) into result;
 return result;
end; $$;

create or replace function public.lothuus_operator_note(actor uuid,note_key uuid,expected_version integer,note_title text,note_body text,note_status text,note_priority text,item_key uuid,due timestamptz) returns void
language plpgsql security invoker set search_path='' as $$
declare previous app_private.operator_notes;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 if length(trim(note_title)) not between 1 and 180 or length(note_body)>6000 or note_status not in ('open','doing','done','archived') or note_priority not in ('normal','high') then raise exception 'INVALID_OPERATOR_INPUT'; end if;
 if item_key is not null and not exists(select 1 from app_private.store cross join lateral jsonb_array_elements(body->'items') i where i->>'id'=item_key::text) then raise exception 'OPERATOR_ITEM_NOT_FOUND'; end if;
 perform 1 from app_private.operator_settings where id for update;
 select * into previous from app_private.operator_notes where id=note_key for update;
 if found then
  if previous.version<>expected_version then raise exception 'OPERATOR_VERSION_CONFLICT'; end if;
  update app_private.operator_notes set title=trim(note_title),body=note_body,status=note_status,priority=note_priority,item_id=item_key,due_at=due,version=version+1,updated_at=now(),actor_id=actor where id=note_key;
 else
  if expected_version<>0 then raise exception 'OPERATOR_VERSION_CONFLICT'; end if;
  if (select count(*) from app_private.operator_notes where status in ('open','doing'))>=200 then raise exception 'OPERATOR_NOTE_LIMIT'; end if;
  insert into app_private.operator_notes(id,title,body,status,priority,item_id,due_at,actor_id) values(note_key,trim(note_title),note_body,note_status,note_priority,item_key,due,actor);
 end if;
 insert into app_private.operator_activity(actor_id,kind,object_id,title,details) values(actor,'note_changed',note_key::text,trim(note_title),jsonb_build_object('status',note_status,'priority',note_priority));
end; $$;
create or replace function public.lothuus_operator_work(actor uuid,note_filter text default 'active') returns jsonb
language plpgsql stable security invoker set search_path='' as $$
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 if note_filter not in ('active','done','archived') then raise exception 'INVALID_OPERATOR_INPUT'; end if;
 return jsonb_build_object('notes',coalesce((select jsonb_agg(to_jsonb(n) order by n.updated_at desc) from (select * from app_private.operator_notes where case note_filter when 'active' then status in ('open','doing') else status=note_filter end order by updated_at desc limit 200) n),'[]'));
end; $$;

create or replace function public.lothuus_operator_job_start(actor uuid,job_key uuid,job_kind text) returns uuid
language plpgsql security invoker set search_path='' as $$
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 if job_kind not in ('backup','measurements') then raise exception 'INVALID_OPERATOR_INPUT'; end if;
 perform 1 from app_private.operator_settings where id for update;
 update app_private.operator_jobs set status='error',finished_at=now(),message='Uitvoering is niet tijdig bevestigd. Controleer de technische toestand.' where status in ('queued','running') and created_at<now()-interval '10 minutes';
 if exists(select 1 from app_private.operator_jobs where status in ('queued','running') or created_at>now()-interval '10 minutes') then raise exception 'OPERATOR_JOB_BUSY'; end if;
 insert into app_private.operator_jobs(id,kind,actor_id) values(job_key,job_kind,actor);
 insert into app_private.operator_activity(actor_id,kind,object_id,title) values(actor,'maintenance_requested',job_key::text,case job_kind when 'backup' then 'Nieuwe reservekopie aangevraagd' else 'Technische metingen aangevraagd' end);
 return job_key;
end; $$;
create or replace function public.lothuus_operator_job_finish(job_key uuid,job_status text,result_message text) returns void
language plpgsql security invoker set search_path='' as $$
begin
 if job_status not in ('running','succeeded','partial','skipped','error') then raise exception 'INVALID_OPERATOR_INPUT'; end if;
 update app_private.operator_jobs set status=job_status,message=left(result_message,500),finished_at=case when job_status='running' then null else now() end where id=job_key and status in ('queued','running');
end; $$;
create or replace function public.lothuus_operator_jobs(actor uuid) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 return coalesce((select jsonb_agg(to_jsonb(j) order by created_at desc) from (select id,kind,case when status in ('queued','running') and created_at<now()-interval '10 minutes' then 'error' else status end as status,created_at,finished_at,case when status in ('queued','running') and created_at<now()-interval '10 minutes' then 'Uitvoering is niet tijdig bevestigd. Controleer de technische toestand.' else message end as message from app_private.operator_jobs order by created_at desc limit 20) j),'[]');
end; $$;
create or replace function public.lothuus_maintenance_claim_manual(job_name text,job_id uuid) returns boolean
language plpgsql security invoker set search_path='' as $$
declare claimed boolean;
begin
 if job_name not in ('backup','supabase-usage') then raise exception 'Invalid job'; end if;
 insert into app_private.maintenance_jobs as j(name,lease_id,lease_until,status) values(job_name,job_id,now()+interval '5 minutes','running')
 on conflict(name) do update set lease_id=job_id,lease_until=now()+interval '5 minutes',status='running'
 where coalesce(j.lease_until,'epoch')<now() and coalesce(j.last_success,'epoch')<now()-interval '10 minutes' returning true into claimed;
 return coalesce(claimed,false);
end; $$;
select cron.schedule('lothuus-operator-workspace-retention','47 3 * * *',$$delete from app_private.operator_versions where captured_at<now()-interval '90 days' or id in (select id from (select id,row_number() over(partition by item_id order by id desc) as position from app_private.operator_versions) versions where position>50);delete from app_private.operator_jobs where created_at<now()-interval '30 days'$$);

create or replace function public.lothuus_operator_pulse(actor uuid) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 with s as (select body from app_private.store where id), reservations as (
 select r,coalesce((select sum(case when p->>'type'='receipt' then (p->>'amountCents')::bigint else -(p->>'amountCents')::bigint end) from jsonb_array_elements(coalesce(r->'payments','[]')) p),0) as paid from s cross join lateral jsonb_array_elements(body->'reservations') r
 ), days as (select d::date as day from generate_series((now() at time zone 'Europe/Brussels')::date-29,(now() at time zone 'Europe/Brussels')::date,interval '1 day') d)
 select jsonb_build_object('collection',public.lothuus_operator_inventory(actor)->'counts',
 'sales',(select jsonb_build_object('active',count(*) filter(where r->>'status'='active'),'completed',count(*) filter(where r->>'status'='completed'),'netReceived',coalesce(sum(paid),0),'overdue',count(*) filter(where r->>'status'='active' and (r->>'deadline')::timestamptz<now() and (coalesce((r->>'paymentPending')::boolean,false) or paid<coalesce((r->>'priceCents')::bigint,0)))) from reservations),
 'lastOwnerActivity',(select max(at) from app_private.operator_activity a where actor_id is not null and not exists(select 1 from app_private.operator_users u where u.user_id=a.actor_id)),
 'trackingSince',(select min(at) from app_private.operator_activity),
 'daily',(select jsonb_agg(jsonb_build_object('day',day,'events',(select count(*) from app_private.operator_activity a where (at at time zone 'Europe/Brussels')::date=day),'products',(select count(*) from app_private.operator_activity a where (at at time zone 'Europe/Brussels')::date=day and kind like 'product_%')) order by day) from days),
 'work',(select jsonb_build_object('open',count(*) filter(where status in ('open','doing')),'high',count(*) filter(where status in ('open','doing') and priority='high'),'overdue',count(*) filter(where status in ('open','doing') and due_at<now())) from app_private.operator_notes),
 'operators',(select coalesce(jsonb_agg(jsonb_build_object('email',email,'enabled',enabled,'createdAt',created_at)),'[]') from app_private.operator_users)) into result;
 return result;
end; $$;
create or replace function public.lothuus_operator_export(actor uuid,export_kind text) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare result jsonb;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN'; end if;
 if export_kind='collection' then
  select jsonb_build_object('total',(select count(*) from app_private.operator_items()),'items',coalesce(jsonb_agg(jsonb_build_object('id',item->>'id','number',coalesce(item->>'productNumber',item->>'sourceReference'),'title',item->>'title','description',item->>'description','priceCents',item->'priceCents','publication',item->>'publication','stock',stock,'missing',missing,'updatedAt',coalesce(item->>'updatedAt',item->>'createdAt'))),'[]')) into result from (select * from app_private.operator_items() limit 5000) p;
 else raise exception 'INVALID_OPERATOR_INPUT'; end if;
 insert into app_private.operator_activity(actor_id,kind,title) values(actor,'export_created','Collectie-export aangemaakt');
 return result;
end; $$;
create or replace function public.lothuus_record_activity(actor uuid,event_kind text,object_key text default null,event_title text default '') returns void
language plpgsql security invoker set search_path='' as $$
begin
 if event_kind not in ('owner_login','superadmin_login','photo_uploaded','capacity_denied','sessions_revoked','export_created') then raise exception 'INVALID_ACTIVITY'; end if;
 if event_kind='capacity_denied' then
  insert into app_private.operator_activity(actor_id,kind,title,dedupe_key)
   values(actor,event_kind,'Toevoeging geweigerd door objectlimiet',coalesce(actor::text,'system')||':capacity:'||to_char(now() at time zone 'UTC','YYYYMMDDHH24MI')) on conflict(dedupe_key) do nothing;
 else
  insert into app_private.operator_activity(actor_id,kind,object_id,title) values(actor,event_kind,left(object_key,100),left(event_title,180));
 end if;
end; $$;

-- Snapshot the new durable workspace too. Earlier complete v2 layouts remain readable.
create or replace function public.lothuus_backup_state() returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare tables jsonb:='{}'; rows jsonb; t text;
begin
 foreach t in array array['store','media','product_numbers','stock_claims','heart_settings','heart_objects','heart_days','analytics_config','analytics_days','hosting_account','hosting_orders','hosting_entitlements','hosting_media_objects','hosting_metrics','hosting_usage_daily','operator_users','operator_settings','operator_activity','operator_notes','operator_versions','operator_jobs'] loop
 execute format('select coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb) from app_private.%I t',t) into rows; tables:=tables||jsonb_build_object(t,rows);
 end loop;
 return jsonb_build_object('schemaVersion',2,'createdAt',now(),'tables',tables);
end; $$;
do $$ declare f record; begin
 for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where
 (n.nspname='public' and p.proname in ('lothuus_operator_inventory','lothuus_operator_product','lothuus_operator_version','lothuus_operator_commit','lothuus_operator_activity_page','lothuus_operator_note','lothuus_operator_work','lothuus_operator_job_start','lothuus_operator_job_finish','lothuus_operator_jobs','lothuus_maintenance_claim_manual','lothuus_operator_pulse','lothuus_operator_export'))
 or (n.nspname='app_private' and p.proname in ('operator_capture_version','operator_items')) loop
 execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end; $$;
commit;
